N=28; sep={4,9,14,19,24}; groups=[[0,1,2,3],[5,6,7,8],[10,11,12,13],[15,16,17,18],[20,21,22,23],[25,26,27]]
out=[[8 if r in sep or c in sep else 0 for c in range(N)] for r in range(N)]
for ri,rg in enumerate(groups):
 for ci,cg in enumerate(groups):
  v=6 if ri in (1,3) and ci==2 else (2 if ri in (1,3) else (3 if ci==2 else 0))
  for r in rg:
   for c in cg: out[r][c]=v
