  v=6 if (rp,cp) in filled2 and (rp,cp) in filled3 else 2 if (rp,cp) in filled2 else 3 if (rp,cp) in filled3 else 0
  for r in rg:
   for c in cg: out[r][c]=v
assert len(out)==28 and all(len(x)==28 for x in out)
print('\n'.join('['+','.join(map(str,row))+'],' for row in out))

